#include "language.hpp"
int main(int argc,char**argv){load(argv[1],argv[2],argv[3],argv[4]);ifstream profiles(argv[5]);float prof;string key;int number=0;while(profiles>>prof>>key){string item;int j=0;for(char c:key){if(c==','){O[j++]=stoi(item);item.clear();}else item+=c;}assert(j==26);auto v=project(O);mt19937 rng(52770121);float best=-1e30;array<int,26>bp;for(int r=0;r<4;r++){for(int i=0;i<26;i++)P[i]=i;shuffle(P.begin(),P.end(),rng);float now=score(P,v);for(int it=0;it<15000;it++){auto pp=P;int a=rng()%26,b=rng()%26;swap(pp[a],pp[b]);float next=score(pp,v),temp=.2+12*(1.-(it%5000)/5000.);if(next>=now||log((rng()+1.)/4294967297.)<(next-now)/temp){P=pp;now=next;if(now>best){best=now;bp=P;}}}}cout<<number++<<' '<<prof<<'\n';emit(best,bp,O);cout<<flush;}}
